 selector='<label>Inspect a mutation <select id="daily-choice"><option value="">Compare all four</option>'+''.join(f'<option value="{m["id"]}">{e(m["name"])}</option>'for m in D['mutations'])+'</select></label>'
 article('daily-mutation','PokeBonk Daily Mutation: Rules & Planning Decisions','Adapt a draft to the Daily Mutation rules','Compare four PokeBonk Daily Mutations, check their fixed conditions, separate prizes from rankings and open a draft with declared-mode checks.','Daily Mutation is a solo Classic-style challenge with shared daily conditions. Pick the variant shown in your game, then adapt the plan to its special rule. The current configuration names the quarter-HP variant Crystal; earlier notes call it Glass.'+ref(1)+ref(2),[('variants','Compare the four mutation decisions',selector+table(['Variant','Difficulty','Checked effect','Planning priority','Next step'],rows)+panels+ref(2)),('entry','Check the actual daily screen before entering','<ol><li>Use the original host and check your League partner.</li><li>Read the daily screen’s map, mutation and difficulty. The shared conditions are not a freely chosen custom mode.</li><li>Do not bring a pre-run Bag or infer co-op support: the mutation mode is solo. Run-found items are a different category.</li><li>Open a declared-mode draft, adjust it and use the warnings to find mismatches. This website does not fetch today’s rotation.</li></ol>'+ref(2)),('reset','Keep daily results and permanent cosmetics separate','<p>The published reset is 00:00 UTC. Attempts are repeatable and the best daily result counts, progression first and KOs next. A better result is not automatically a new permanent cosmetic claim.</p>'+table(['Cosmetic condition','What to check'],[['Reach zone 3','Mutation-specific title'],['Reach the shrine','Mutation-specific frame'],['Win','Mutation-specific profile background'],['Win all four variants','Mutation King title']])+'<p>These are the current configuration’s unlock conditions. This guide has not claimed a prize or reproduced the reset boundary. Follow the current reward screen if its state differs.</p>'+ref(2)),('limits','Use a plan without assuming a winning roll','<p>The variant decisions are editorial interpretations of checked rules, not benchmarked builds. Keep the first useful attack, inspect later offers and record what actually ended the attempt. A saved plan does not unlock a partner, grant items or guarantee a leaderboard result.</p>')],sources,[('build-planner/','Keep a complete declared plan'),('updates/','Read release-specific corrections'),('time-attack/','Separate Classic medals from daily ranking')])
 clock='<div class="tool"><label>Minutes since the last machine use <input id="machine-minutes" type="number" min="0" max="1440" value="0"></label><label>Seconds <input id="machine-seconds" type="number" min="0" max="59" value="0"></label><button type="button" id="machine-check">Check reuse threshold</button><p id="machine-result" role="status">Enter elapsed time; no live game clock is read.</p></div><noscript><p>The documented reuse threshold is eleven minutes after use; the calculator requires JavaScript.</p></noscript>'
 article('team-survival','PokeBonk Team Survival: Co-op Rules & Fusion Timing','Prepare a team without importing solo milestones','Check PokeBonk Team Survival entry, shared boss and revival rules, fusion-machine reuse timing and declared plans without copying solo milestones.','Select Survival in a co-op room using a registered account. Team Survival uses a shared boss every four minutes and returns fallen players when the surviving team beats the next boss. It is separate from solo Survival’s five-minute schedule.'+ref(1)+ref(2),[('entry','Prepare the room and the declarations','<ol><li>Check that each trainer can access current co-op with an account.</li><li>Choose a friends’ room or public matchmaking, then Survival, team size, map and difficulty.</li><li>Agree who calls objectives and use the G / L3 signal wheel for locations or danger. The crowned public leader starts the room.</li><li>Save each trainer’s own declared plan. This website does not synchronize a live team.</li></ol>'+ref(2)),('milestones','Use the team rule at a shared boss',table(['Situation','Decision','Avoid assuming'],[['A teammate is down','The surviving team must beat the next boss for the documented revival.','A guaranteed timed self-revive.'],['Approaching a boss interval','Reassess movement, recovery and the next shared objective.','The solo 45-minute Mewtwo sequence.'],['Choosing upgrades','Watch finite protection: five seconds per level, capped at ten.','An indefinitely safe menu.'],['Room leader idle','Watch crown transfer and Still there? in public rooms.','A permanently stuck lobby.']])+ref(2)),('machine','Check the Team Survival fusion-machine interval',clock+'<p>The .72 notes say Bill’s Machine works again eleven minutes after use. The check below only evaluates elapsed time. It cannot prove a machine is present, usable in your current state or offered with the right ingredients. Fusion ingredients and slot choices are still checked separately.</p>'+ref(2)),('roles','Make the next attempt answer a specific problem','<p>Choose practical responsibilities before starting: objective calls, watching incoming pressure and signaling recovery or movement. These are planning suggestions, not mandatory game classes. If a run ends, record whether the problem was an unmet mechanic, a missed signal, an unavailable item or an unhelpful kit before replacing the whole build.</p><p>The release names Cataclysm and Apocalypse, but this guide does not invent unverified stage timings or claim a completed team clear.</p>')],sources,[('multiplayer/','Use the current matchmaking checklist'),('survival/','Read the separate solo reference'),('move-fusions/','Check fusion ingredients'),('build-planner/','Save a declared team-mode plan')])
